export function createOrUpdate(n,t,e,r){return r!==void 0?(r[0]=n,r[1]=t,r[2]=e,r):[n,t,e]}export function getKeyZXY(n,t,e){return n+"/"+t+"/"+e}export function getKey(n){return getKeyZXY(n[0],n[1],n[2])}export function getCacheKeyForTileKey(n){const[t,e,r]=n.substring(n.lastIndexOf("/")+1,n.length).split(",").map(Number);return getKeyZXY(t,e,r)}export function fromKey(n){return n.split("/").map(Number)}export function hash(n){return(n[1]<<n[0])+n[2]}export function withinExtentAndZ(n,t){const e=n[0],r=n[1],c=n[2];if(t.getMinZoom()>e||e>t.getMaxZoom())return!1;const u=t.getFullTileRange(e);return u?u.containsXY(r,c):!0}
